function check_colision(s,w,h)
	local c = {}
	for i = 0, w do
		c[i]={}
		for j = 0, h do
			c[i][j]=solid[
				mget(
					(s.x+s.vx+i)//cell,
					(s.y+s.vy+j)//cell
				)
			]
		end
	end
	return c
end

plr={
 x = 33, y = 32,
 vx = 0, vy = 0,
 a = 0.8,
 
 direction="down",
 sprs={
  ["down"]={256},
  ["up"]={256},
  ["left"]={256},
  ["right"]={256}
 },
 
 move = function(s)
  if btn(0) then 
   s.vy = -s.a 
   s.direction = "up"
  elseif btn(1) then
   s.vy = s.a 
   s.direction = "down" 
  else 
   s.vy = 0
  end
  if btn(2) then 
   s.vx = -s.a 
   s.direction = "left"
  elseif btn(3) then
   s.vx = s.a 
   s.direction = "right" 
  else 
   s.vx = 0
  end
  
  local pc = check_colision(s, cell, cell)
  
	if 
		pc[0][0] == colision_types.full or pc[0][4] == colision_types.full or pc[0][8] == colision_types.full or 
		pc[0][12] == colision_types.full or pc[0][cell-1] == colision_types.full or pc[cell][1] == colision_types.full or 
		pc[cell][4] == colision_types.full or pc[cell][8] == colision_types.full or pc[cell][12] == colision_types.full or 
		pc[cell][cell-1] == colision_types.full 
	then
		s.vx = -s.vx
	end
	if 
		pc[0][0] == colision_types.full or pc[4][0] == colision_types.full or pc[8][0] == colision_types.full or 
		pc[12][0] == colision_types.full or pc[cell-1][0] == colision_types.full or pc[1][cell] == colision_types.full or 
		pc[4][cell] == colision_types.full or pc[8][cell] == colision_types.full or pc[12][cell] == colision_types.full or 
		pc[cell-1][cell] == colision_types.full 
	then
		s.vy = -s.vy
	end
	
	--[[for i = 0, #pc do
		for j = 0, #pc[i] do
			pix(i, j, pc[i][j]*15)
		end
	end]]
  
  s.y = s.y + s.vy
  s.x = s.x + s.vx
 end,
 draw = function(s)
  local spr_=1
  if s.vx~=0 or s.vy~=0 then
   spr_=1+((t//4)%(#s.sprs[s.direction]==0 and 1 or #s.sprs[s.direction]))
  end
  
  spr(
   s.sprs[s.direction][spr_],
   math.min(s.x,112), math.min(s.y,60), 
   -1,
   2
  )
	--[[local i = 0
	for k, s in pairs(plr) do
		print((s), 0,i)
		i=i+6
	end]]
  --print(s.sprs[s.direction][spr_])
 end
}

mapa = {
 x = math.max(plr.x, 0),
 y = math.max(plr.y, 0),
 move = function(s)
  s.x = math.max(plr.x-112, 0)
  s.y = math.max(plr.y-60, 0)
 end,
 draw = function(s)
  map(
   s.x//16,s.y//16,
   31,17,
   -(s.x%16),-(s.y%16),
   -1,
   2
  )
 end
}

function art_demonstration_room()
 --UPDATE
 mapa:move()
 plr:move()
 
 --GRAPHICS
 mapa:draw()
 
 plr:draw()
end

function TIC()
 gstart="art demonstration room"
 
 if gstart=="visualization" then
  if 1>=t then init_visualization_of_drawings(0) end
  visualization_of_drawings()
 elseif gstart=="art demonstration room" then
  art_demonstration_room()
 elseif gstart=="menu" then
 
 end
 
 t=t+1
end

